package com.yilu.yinling.ai.client;
import lombok.Getter; import org.springframework.stereotype.Component;
@Component @Getter public class LlmRuntimeState { private volatile boolean available; private volatile boolean fallback=true; private volatile String message="not called"; private volatile long requestTime; private volatile long responseTime; private volatile LlmCallMetrics lastMetrics; public void success(long s,long e,String provider,String model,int length){available=true;fallback=false;message="SUCCESS";requestTime=s;responseTime=e;lastMetrics=new LlmCallMetrics(provider,model,true,false,e-s,java.time.Instant.now(),length);} public void fallback(long s,long e,String reason){available=false;fallback=true;message=reason==null?"using mock":"using mock: "+reason;requestTime=s;responseTime=e;lastMetrics=new LlmCallMetrics("unknown","unknown",false,true,e-s,java.time.Instant.now(),0);} }
